# /// script
# dependencies = []
# ///
from pathlib import Path
import json
P=Path(__file__).parent
rows=json.loads((P/'data/survival-overall.json').read_text())['rows']+json.loads((P/'data/survival-by-editor.json').read_text())['rows']
html='''<!doctype html><html><head><meta charset="utf-8"><style>:root{color-scheme:dark;font-family:var(--font-sans,system-ui)}h3{margin:8px 0}p{color:var(--muted-foreground,#aaa);font-size:13px}svg{width:100%;height:310px}select{background:var(--card,#222);color:var(--foreground,#eee);padding:8px;border:1px solid var(--border,#555);border-radius:6px}text{fill:var(--foreground,#ddd);font-size:12px}line{stroke:var(--border,#555)}.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:13px}</style></head><body><h3>How long does Wikipedia wording survive?</h3><select id="mode"><option value="overall">Wording versus inferred slot</option><option value="editor">Named versus anonymous introductions</option></select><svg viewBox="0 0 700 310" id="chart"></svg><div class="legend" id="legend"></div><p>Prose ≥80 characters. Kaplan–Meier; snapshot 1 Oct 2026. Logarithmic age axis. Undone removals censored; raw sensitivity counts all endings. Slot follows rewordings and returns, including gaps. Unsupported tails omitted.</p><script>const rows=DATA;const colors=['var(--chart-1,#60a5fa)','var(--chart-2,#34d399)','var(--chart-3,#fbbf24)'];function draw(){let mode=document.getElementById('mode').value;let series=mode==='overall'?[['wording','all','Exact wording'],['slot','all','Inferred slot'],['wording_raw','all','Raw wording endings']]:[['wording','named','Named'],['wording','anonymous','Anonymous']];let x=t=>55+(Math.log10(t)-Math.log10(3600))/(Math.log10(20*365.25*86400)-Math.log10(3600))*620,y=s=>260-225*s;let html='';for(let v=0;v<=1.001;v+=.25)html+=`<line x1="55" y1="${y(v)}" x2="675" y2="${y(v)}"/><text x="10" y="${y(v)+4}">${Math.round(v*100)}%</text>`;for(let [t,label] of [[3600,'1h'],[86400,'1d'],[30*86400,'1mo'],[365.25*86400,'1y'],[5*365.25*86400,'5y'],[20*365.25*86400,'20y']])html+=`<text x="${x(t)}" y="285" text-anchor="middle">${label}</text>`;series.forEach(([ep,g,label],i)=>{let pts=rows.filter(r=>r.dimension===mode&&r.endpoint===ep&&r.grp===g&&r.age_seconds>=3600&&r.survival!==null).sort((a,b)=>a.age_seconds-b.age_seconds);html+=`<polyline fill="none" stroke="${colors[i]}" stroke-width="2.5" points="${pts.map(r=>x(r.age_seconds)+','+y(r.survival)).join(' ')}"/>`;for(let r of pts)html+=`<circle cx="${x(r.age_seconds)}" cy="${y(r.survival)}" r="3" fill="${colors[i]}"><title>${label}: ${(r.age_seconds/86400).toFixed(2)} days; S=${(100*r.survival).toFixed(2)}%; at risk ${r.at_risk}</title></circle>`});document.getElementById('chart').innerHTML=html;document.getElementById('legend').innerHTML=series.map((s,i)=>`<span style="color:${colors[i]}">● ${s[2]}</span>`).join('')}document.getElementById('mode').onchange=draw;draw();</script></body></html>'''.replace('DATA',json.dumps(rows))
(P/'survival.html').write_text(html)
